16	+// AuthSession is a single active login session — an OAuth refresh-token family —
17	+// returned by entire-core's session endpoint. One is created per
18	+// `entire login`, across all of a user's devices. Plaintext token values are
19	+// never returned by the server, only metadata. (The list envelope's wire key
20	+// is "tokens"; the rows are sessions.)
21	+type AuthSession struct {
22	+	ID         string  `json:"id"`
23	+	UserID     string  `json:"user_id"`
24	+	Name       string  `json:"name"`
25	+	Scope      string  `json:"scope"`
