42	+	if c.authSessionsPath == "" {
43	+		return "", errAuthSessionsPathUnset
44	+	}
45	+	return c.authSessionsPath, nil
46	+}
47	+
48	+// ListAuthSessions returns the authenticated user's active login sessions.
49	+func (c *Client) ListAuthSessions(ctx context.Context) ([]AuthSession, error) {
50	+	base, err := c.authSessionsBasePath()
51	+	if err != nil {
52	+		return nil, fmt.Errorf("list sessions: %w", err)
53	+	}
54	+	resp, err := c.Get(ctx, base)
55	+	if err != nil {
56	+		return nil, fmt.Errorf("list sessions: %w", err)
57	+	}
58	+	defer resp.Body.Close()
59	+
60	+	if err := CheckResponse(resp); err != nil {
61	+		return nil, fmt.Errorf("list sessions: %w", err)
62	+	}
63	+
64	+	var out AuthSessionsResponse
65	+	if err := DecodeJSON(resp, &out); err != nil {
66	+		return nil, fmt.Errorf("list sessions: %w", err)
67	+	}
68	+	return out.Sessions, nil
69	+}
