71	+// RevokeCurrentAuthSession revokes the login session this client is authenticating
72	+// with (the family the current bearer belongs to).
73	+func (c *Client) RevokeCurrentAuthSession(ctx context.Context) error {
74	+	base, err := c.authSessionsBasePath()
75	+	if err != nil {
76	+		return fmt.Errorf("revoke current session: %w", err)
77	+	}
78	+	resp, err := c.Delete(ctx, base+"/current")
79	+	if err != nil {
80	+		return fmt.Errorf("revoke current session: %w", err)
81	+	}
82	+	defer resp.Body.Close()
83	+
84	+	if err := CheckResponse(resp); err != nil {
85	+		return fmt.Errorf("revoke current session: %w", err)
86	+	}
87	+	return nil
88	+}
89	+
90	+// RevokeAuthSession revokes the login session with the given id.
91	+func (c *Client) RevokeAuthSession(ctx context.Context, id string) error {
92	+	base, err := c.authSessionsBasePath()
93	+	if err != nil {
94	+		return fmt.Errorf("revoke session %s: %w", id, err)
95	+	}
96	+	resp, err := c.Delete(ctx, base+"/"+url.PathEscape(id))
97	+	if err != nil {
98	+		return fmt.Errorf("revoke session %s: %w", id, err)
99	+	}
100	+	defer resp.Body.Close()
101	+
102	+	if err := CheckResponse(resp); err != nil {
103	+		return fmt.Errorf("revoke session %s: %w", id, err)
104	+	}
105	+	return nil
106	+}
